package com.greenocean.backend.auth.service;
import com.yubico.webauthn.*;import com.yubico.webauthn.data.*;import org.springframework.stereotype.Repository;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.nio.charset.StandardCharsets;
@Repository public class WebAuthnCredentials implements CredentialRepository {
 private final JdbcTemplate db;public WebAuthnCredentials(JdbcTemplate db){this.db=db;}
 private static ByteArray decode(String value){try{return ByteArray.fromBase64Url(value);}catch(Exception e){throw new IllegalStateException("Invalid stored security key");}}
 public static ByteArray handle(UUID user){return new ByteArray(user.toString().getBytes(StandardCharsets.UTF_8));}
 private static UUID id(ByteArray handle){return UUID.fromString(new String(handle.getBytes(),StandardCharsets.UTF_8));}
 public Set<PublicKeyCredentialDescriptor> getCredentialIdsForUsername(String username){try{return new HashSet<>(db.query("SELECT credential_id FROM webauthn_credentials WHERE user_id=? AND revoked_at IS NULL",(rs,n)->PublicKeyCredentialDescriptor.builder().id(decode(rs.getString(1))).build(),UUID.fromString(username)));}catch(Exception e){return Set.of();}}
 public Optional<ByteArray> getUserHandleForUsername(String username){try{UUID user=UUID.fromString(username);return Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM users WHERE id=? AND status='ACTIVE')",Boolean.class,user))?Optional.of(handle(user)):Optional.empty();}catch(Exception e){return Optional.empty();}}
 public Optional<String> getUsernameForUserHandle(ByteArray handle){try{var user=id(handle);return getUserHandleForUsername(user.toString()).map(v->user.toString());}catch(Exception e){return Optional.empty();}}
 public Optional<RegisteredCredential> lookup(ByteArray credential,ByteArray handle){try{return db.query("SELECT credential_id,public_key_cose,signature_count FROM webauthn_credentials WHERE credential_id=? AND user_id=? AND revoked_at IS NULL",(rs,n)->RegisteredCredential.builder().credentialId(decode(rs.getString(1))).userHandle(handle).publicKeyCose(decode(rs.getString(2))).signatureCount(rs.getLong(3)).build(),credential.getBase64Url(),id(handle)).stream().findFirst();}catch(Exception e){return Optional.empty();}}
 public Set<RegisteredCredential> lookupAll(ByteArray credential){var users=db.queryForList("SELECT user_id FROM webauthn_credentials WHERE credential_id=? AND revoked_at IS NULL",UUID.class,credential.getBase64Url());var result=new HashSet<RegisteredCredential>();for(var user:users)lookup(credential,handle(user)).ifPresent(result::add);return result;}
}
